#include <iostream>
#include <vector>
#include <map>

using namespace std;

int main() {
    long long N, X, M;
    cin >> N >> X >> M;

    vector<long long> A;
    map<long long, int> seen;

    long long current = X;
    long long sum = 0;

    int cycle_start = -1;
    for (int i = 0; i < N; ++i) {
        if (seen.count(current)) {
            cycle_start = seen[current];
            break;
        }
        seen[current] = i;
        A.push_back(current);
        sum += current;
        current = (current * current) % M;
    }

    if (cycle_start == -1) {
        cout << sum << endl;
    } else {
        long long pre_cycle_sum = 0;
        for (int i = 0; i < cycle_start; ++i) {
            pre_cycle_sum += A[i];
        }

        long long cycle_sum = 0;
        for (int i = cycle_start; i < A.size(); ++i) {
            cycle_sum += A[i];
        }

        long long cycle_len = A.size() - cycle_start;
        long long remaining_n = N - cycle_start;

        long long num_cycles = remaining_n / cycle_len;
        long long remainder = remaining_n % cycle_len;

        long long total_sum = pre_cycle_sum + num_cycles * cycle_sum;
        for (int i = 0; i < remainder; ++i) {
            total_sum += A[cycle_start + i];
        }

        cout << total_sum << endl;
    }

    return 0;
}
