#include <string>
#include <algorithm>
#include <cmath>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    int n;
    cin >> s >> n;

    vector<int> count(26, 0);
    vector<bool> present(26, false);
    for (char c : s) {
        count[c - 'a']++;
        present[c - 'a'] = true;
    }

    int distinct_chars = 0;
    for (int i = 0; i < 26; ++i) {
        if (present[i]) distinct_chars++;
    }

    if (distinct_chars > n) {
        cout << -1 << endl;
        return 0;
    }

    int min_sheets = -1;
    string best_sheet = "";

    // Binary search for the minimum number of sheets k
    int low = 1, high = s.length();
    while (low <= high) {
        int k = low + (high - low) / 2;

        vector<pair<int, int>> needed;
        for (int i = 0; i < 26; ++i) {
            if (present[i]) {
                needed.push_back({(count[i] + k - 1) / k, i});
            }
        }

        int sum_needed = 0;
        for (auto& p : needed) sum_needed += p.first;

        if (sum_needed <= n) {
            min_sheets = k;
            best_sheet = "";
            for (auto& p : needed) {
                for (int j = 0; j < p.first; ++j) best_sheet += (char)('a' + p.second);
            }
            while (best_sheet.length() < n) best_sheet += 'a';
            high = k - 1;
        } else {
            low = k + 1;
        }
    }

    if (min_sheets == -1) {
        cout << -1 << endl;
    } else {
        cout << min_sheets << endl;
        cout << best_sheet << endl;
    }

    return 0;
}
