int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    string s;
    cin >> s;

    if (n % 2 != 0) {
        cout << ":(" << endl;
        return 0;
    }

    int open_needed = n / 2;
    int close_needed = n / 2;

    for (char c : s) {
        if (c == '(') open_needed--;
        else if (c == ')') close_needed--;
    }

    if (open_needed < 0 || close_needed < 0) {
        cout << ":(" << endl;
        return 0;
    }

    string res = s;
    for (int i = 0; i < n; ++i) {
        if (res[i] == '?') {
            if (open_needed > 0) {
                res[i] = '(';
                open_needed--;
            } else {
                res[i] = ')';
                close_needed--;
            }
        }
    }

    int balance = 0;
    for (int i = 0; i < n; ++i) {
        if (res[i] == '(') balance++;
        else balance--;

        if (i < n - 1 && balance <= 0) {
            cout << ":(" << endl;
            return 0;
        }
    }

    if (balance != 0) {
        cout << ":(" << endl;
    } else {
        cout << res << endl;
    }

    return 0;
}
