#include <iostream>
#include <string>
#include <vector>

using namespace std;

bool solve() {
    int n;
    cin >> n;
    string s, t;
    cin >> s >> t;

    vector<pair<char, char>> diff;
    for (int i = 0; i < n; ++i) {
        if (s[i] != t[i]) {
            diff.push_back({s[i], t[i]});
        }
    }

    if (diff.size() != 2) {
        return false;
    }

    // We have two positions i and j where s[i] != t[i] and s[j] != t[j].
    // Let the differences be (s[i], t[i]) and (s[j], t[j]).
    // We need to swap one char from s and one from t to make them equal.
    // This means after the swap, s[i] must equal t[i] and s[j] must equal t[j].

    char s1 = diff[0].first, t1 = diff[0].second;
    char s2 = diff[1].first, t2 = diff[1].second;

    // Case 1: Swap s[i] and t[j]
    if (s1 == s2 && t1 == t2) return true;
    // Case 2: Swap s[i] and t[i] (not useful here as it doesn't fix both)
    // Case 3: Swap s[i] and t[j] where s1 == s2 and t1 == t2
    // Case 4: Swap s[i] and t[j] such that s1 == s2 and t1 == t2
    // Basically, we need the set of characters {s1, t1, s2, t2} to be such that
    // one swap fixes both.
    // The possible configurations for 2 mismatches are:
    // 1. s1 == s2 and t1 == t2 (e.g., s="ab", t="ba" -> s1='a', t1='b', s2='b', t2='a')
    //    Swap s[i] and t[j]: s becomes s1, t becomes t1. Correct.
    if (s1 == s2 && t1 == t2) return true;
    if (s1 == t1 && s2 == t2) return true; // Should not happen based on diff logic
    if (s1 == t2 && s2 == t1) return true;

    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int k;
    cin >> k;
    while (k--) {
        if (solve()) cout << "Yes" << endl;
        else cout << "No" << endl;
    }
    return 0;
}
