    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    int m;
    cin >> m;
    vector<long long> b(m);
    for (int i = 0; i < m; ++i) cin >> b[i];

    int i = 0, j = 0;
    int count = 0;
    long long sumA = a[0], sumB = b[0];

    while (i < n && j < m) {
        if (sumA == sumB) {
            count++;
            i++;
            j++;
            if (i < n) sumA = a[i];
            if (j < m) sumB = b[j];
        } else if (sumA < sumB) {
            i++;
            if (i < n) sumA += a[i];
        } else {
            j++;
            if (j < m) sumB += b[j];
        }
    }

    if (i == n && j == m) {
        cout << count << endl;
    } else {
        cout << -1 << endl;
    }

    return 0;
}
